      const nx = (rec.pos.x | 0) + dir.dx;
      const ny = (rec.pos.y | 0) + dir.dy;
      if (isWalkable(nx, ny)) {
        try { world.add(id, MoveIntent, { dx: dir.dx, dy: dir.dy }); } catch {}
      }
    }
  }
}

